import imagehash
from PIL import Image

def compute_phash(img_path, hash_size=8):
    try:
        with Image.open(img_path) as img:
            return str(imagehash.phash(img, hash_size=8))
    except:
        return None

df['perceptual_hash'] = df['path'].apply(lambda p: compute_phash(p, 8))
